'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  const script = [];
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) {
    script.push({ op: 'equal', line: a[start++] });
  }

  let oldEnd = a.length;
  let newEnd = b.length;
  while (oldEnd > start && newEnd > start && a[oldEnd - 1] === b[newEnd - 1]) {
    oldEnd--;
    newEnd--;
  }
  const n = oldEnd - start;
  const m = newEnd - start;

  if (n === 0 || m === 0) {
    for (let i = start; i < oldEnd; i++) script.push({ op: 'delete', line: a[i] });
    for (let i = start; i < newEnd; i++) script.push({ op: 'insert', line: b[i] });
  } else {
    // Myers' frontier: diagonal k stores the furthest old-side position.
    // Keep only 2*d + 1 slots per layer, rather than copying N + M slots.
    // Trace storage is O(D^2); the search takes O((N + M) * D) time.
    const trace = [];
    let distance = 0;
    search: for (let d = 0; d <= n + m; d++) {
      const frontier = new Int32Array(2 * d + 1);
      const previous = trace[d - 1];
      for (let k = -d; k <= d; k += 2) {
        let x;
        if (d === 0) {
          x = 0;
        } else if (k === -d ||
                   (k !== d && previous[k - 1 + d - 1] < previous[k + 1 + d - 1])) {
          x = previous[k + 1 + d - 1];
        } else {
          x = previous[k - 1 + d - 1] + 1;
        }
        let y = x - k;
        while (x < n && y < m && a[start + x] === b[start + y]) {
          x++;
          y++;
        }
        frontier[k + d] = x;
        if (x === n && y === m) {
          trace.push(frontier);
          distance = d;
          break search;
        }
      }
      trace.push(frontier);
    }

    const reversed = [];
    let x = n;
    let y = m;
    for (let d = distance; d > 0; d--) {
      const k = x - y;
      const previous = trace[d - 1];
      const insertion = k === -d ||
        (k !== d && previous[k - 1 + d - 1] < previous[k + 1 + d - 1]);
      const previousK = insertion ? k + 1 : k - 1;
      const previousX = previous[previousK + d - 1];
      const previousY = previousX - previousK;
      while (x > previousX && y > previousY) {
        reversed.push({ op: 'equal', line: a[start + --x] });
        y--;
      }
      if (insertion) {
        reversed.push({ op: 'insert', line: b[start + --y] });
      } else {
        reversed.push({ op: 'delete', line: a[start + --x] });
      }
    }
    while (x > 0 && y > 0) {
      reversed.push({ op: 'equal', line: a[start + --x] });
      y--;
    }

    // A shortest path may interleave insertions and deletions. Reorder only
    // within change regions, preserving both inputs and the chosen LCS.
    for (let i = reversed.length - 1; i >= 0;) {
      if (reversed[i].op === 'equal') {
        script.push(reversed[i--]);
        continue;
      }
      const deletes = [];
      const inserts = [];
      while (i >= 0 && reversed[i].op !== 'equal') {
        const entry = reversed[i--];
        (entry.op === 'delete' ? deletes : inserts).push(entry);
      }
      for (const entry of deletes) script.push(entry);
      for (const entry of inserts) script.push(entry);
    }
  }

  for (let i = oldEnd; i < a.length; i++) script.push({ op: 'equal', line: a[i] });
  return script;
}

/**
 * Return unified hunks: [{ oldStart, oldLines, newStart, newLines, lines }].
 * context is a nonnegative integer, default 3. Hunk lines are original strings
 * prefixed with ' ' (equal), '-' (delete), or '+' (insert); remove exactly one
 * prefix to recover a line, even when the original starts with a prefix itself.
 * oldLines counts context + deletes; newLines counts context + inserts.
 * Include up to context unchanged lines before/after each changed region.
 * Merge regions if the intervening unchanged gap is <= 2 * context (their
 * context would touch or overlap). Do not duplicate context in merged hunks.
 * Starts are 1-based, except a zero-line range names the line BEFORE the range:
 * oldLines === 0 uses the preceding old line number (0 for insertion at top),
 * and newLines === 0 uses the preceding new line number (0 for deletion at top).
 * Coordinates refer to the complete original a and result b, not a local hunk.
 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  if (!Number.isSafeInteger(context) || context < 0) {
    throw new RangeError('context must be a nonnegative integer');
  }
  const script = diffLines(a, b);
  const ranges = [];
  for (let i = 0; i < script.length;) {
    if (script[i].op === 'equal') {
      i++;
      continue;
    }
    const start = Math.max(0, i - context);
    while (i < script.length && script[i].op !== 'equal') i++;
    const end = Math.min(script.length, i + context);
    const previous = ranges[ranges.length - 1];
    if (previous && start <= previous.end) {
      previous.end = Math.max(previous.end, end);
    } else {
      ranges.push({ start, end });
    }
  }

  const hunks = [];
  let cursor = 0;
  let oldPosition = 0;
  let newPosition = 0;
  for (const range of ranges) {
    while (cursor < range.start) {
      const entry = script[cursor++];
      if (entry.op !== 'insert') oldPosition++;
      if (entry.op !== 'delete') newPosition++;
    }
    const oldBefore = oldPosition;
    const newBefore = newPosition;
    const lines = [];
    while (cursor < range.end) {
      const entry = script[cursor++];
      const prefix = entry.op === 'equal' ? ' ' : entry.op === 'delete' ? '-' : '+';
      lines.push(prefix + entry.line);
      if (entry.op !== 'insert') oldPosition++;
      if (entry.op !== 'delete') newPosition++;
    }
    const oldLines = oldPosition - oldBefore;
    const newLines = newPosition - newBefore;
    hunks.push({
      oldStart: oldBefore + (oldLines === 0 ? 0 : 1),
      oldLines,
      newStart: newBefore + (newLines === 0 ? 0 : 1),
      newLines,
      lines,
    });
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  if (!Array.isArray(hunks)) throw new Error('hunk 0 does not apply: expected an array');
  const result = [];
  let cursor = 0;
  for (let index = 0; index < hunks.length; index++) {
    const fail = () => {
      throw new Error(`hunk ${index} does not apply`);
    };
    const hunk = hunks[index];
    if (!hunk || typeof hunk !== 'object' || !Array.isArray(hunk.lines)) fail();
    for (const key of ['oldStart', 'oldLines', 'newStart', 'newLines']) {
      if (!Number.isSafeInteger(hunk[key]) || hunk[key] < 0) fail();
    }
    if ((hunk.oldLines > 0 && hunk.oldStart === 0) ||
        (hunk.newLines > 0 && hunk.newStart === 0)) fail();

    const oldIndex = hunk.oldStart - (hunk.oldLines > 0 ? 1 : 0);
    const newIndex = hunk.newStart - (hunk.newLines > 0 ? 1 : 0);
    if (oldIndex < cursor || oldIndex > a.length ||
        hunk.oldLines > a.length - oldIndex ||
        newIndex !== result.length + oldIndex - cursor) fail();

    while (cursor < oldIndex) result.push(a[cursor++]);
    let oldCount = 0;
    let newCount = 0;
    for (const line of hunk.lines) {
      if (typeof line !== 'string' || line.length === 0) fail();
      const prefix = line[0];
      const text = line.slice(1);
      if (prefix === ' ' || prefix === '-') {
        if (oldCount >= hunk.oldLines || cursor >= a.length || a[cursor] !== text) fail();
        cursor++;
        oldCount++;
      } else if (prefix !== '+') {
        fail();
      }
      if (prefix === ' ' || prefix === '+') {
        if (newCount >= hunk.newLines) fail();
        result.push(text);
        newCount++;
      }
    }
    if (oldCount !== hunk.oldLines || newCount !== hunk.newLines) fail();
  }
  while (cursor < a.length) result.push(a[cursor++]);
  return result;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

